function main() {
    $n = (int)trim(fgets(STDIN));
    $s = trim(fgets(STDIN));
    $m = strlen($s);

    if ($m > $n) {
        echo 0 . "\n";
        return;
    }

    // Precompute the failure function (partial match table) for the KMP automaton
    $failure = array_fill(0, $m + 1, 0);
    for ($i = 1; $i < $m; ++$i) {
        $j = $failure[$i];
        while ($j > 0 && $s[$i] != $s[$j]) {
            $j = $failure[$j];
        }
        $failure[$i + 1] = ($s[$i] == $s[$j]) ? $j + 1 : 0;
    }

    // Precompute transitions for the KMP automaton
    $transitions = array_fill(0, $m + 1, array(0, 0));
    for ($state = 0; $state <= $m; ++$state) {
        for ($bit = 0; $bit <= 1; ++$bit) {
            $char = ($bit == 0) ? '0' : '1';
            if ($state < $m && $s[$state] == $char) {
                $transitions[$state][$bit] = $state + 1;
            } else {
                if ($state == 0) {
                    $transitions[$state][$bit] = 0;
                } else {
                    $transitions[$state][$bit] = $transitions[$failure[$state]][$bit];
                }
            }
        }
    }

    // DP initialization
    $dp = array_fill(0, $m + 1, 0);
    $dp[0] = 1;

    // Fill DP table
    for ($i = 0; $i < $n; ++$i) {
        $nextDp = array_fill(0, $m + 1, 0);
        for ($state = 0; $state <= $m; ++$state) {
            if ($dp[$state] == 0) continue;
            for ($bit = 0; $bit <= 1; ++$bit) {
                $nextState = $transitions[$state][$bit];
                $nextDp[$nextState] += $dp[$state];
            }
        }
        $dp = $nextDp;
    }

    // Sum all states except the accepting state (m)
    $total = 0;
    for ($state = 0; $state < $m; ++$state) {
        $total += $dp[$state];
    }

    $result = (1 << $n) - $total;
    echo $result . "\n";
}

main();
