<?php
function computeLPS($pattern) {
    $m = strlen($pattern);
    $lps = array_fill(0, $m, 0);
    $len = 0;
    $i = 1;
    while ($i < $m) {
        if ($pattern[$i] == $pattern[$len]) {
            $len++;
            $lps[$i] = $len;
            $i++;
        } else {
            if ($len != 0) {
                $len = $lps[$len - 1];
            } else {
                $lps[$i] = 0;
                $i++;
            }
        }
    }
    return $lps;
}

function kmpSearch($text, $pattern) {
    $n = strlen($text);
    $m = strlen($pattern);
    $lps = computeLPS($pattern);
    $i = 0;
    $j = 0;
    while ($i < $n) {
        if ($pattern[$j] == $text[$i]) {
            $i++;
            $j++;
        }
        if ($j == $m) {
            return true;
        } elseif ($i < $n && $pattern[$j] != $text[$i]) {
            if ($j != 0) {
                $j = $lps[$j - 1];
            } else {
                $i++;
            }
        }
    }
    return false;
}

$n = intval(trim(fgets(STDIN)));
$s = trim(fgets(STDIN));
$m = strlen($s);

if ($m > $n) {
    echo 0 . "\n";
    exit;
}

// Compute failure function for s
$lps = computeLPS($s);

// Build transition table for KMP automaton
$trans = array();
for ($state = 0; $state < $m; $state++) {
    for ($c = 0; $c <= 1; $c++) {
        $char = chr($c + ord('0'));
        $newState = $state;
        while ($newState > 0 && $char != $s[$newState]) {
            $newState = $lps[$newState - 1];
        }
        if ($char == $s[$newState]) {
            $newState++;
        }
        $trans[$state][$c] = $newState;
    }
}

// DP[i][state] = number of ways to build string of length i, ending in KMP state 'state'
$dp = array();
for ($i = 0; $i <= $n; $i++) {
    $dp[$i] = array_fill(0, $m, 0);
}
$dp[0][0] = 1;

for ($i = 0; $i < $n; $i++) {
    for ($state = 0; $state < $m; $state++) {
        if ($dp[$i][$state] == 0) continue;
        for ($c = 0; $c <= 1; $c++) {
            $newState = $trans[$state][$c];
            if ($newState < $m) {
                $dp[$i + 1][$newState] += $dp[$i][$state];
            }
        }
    }
}

// Total number of binary strings of length n
$total = 1 << $n;

// Number of strings that do NOT contain s as a substring
$notContain = 0;
for ($state = 0; $state < $m; $state++) {
    $notContain += $dp[$n][$state];
}

// Answer is total - notContain
$answer = $total - $notContain;

echo $answer . "\n";
?>
