<?php
function main() {
    $n = (int)trim(fgets(STDIN));
    $s = trim(fgets(STDIN));
    $m = strlen($s);

    if ($m > $n) {
        echo 0;
        return;
    }

    // Build failure function for KMP
    $fail = array_fill(0, $m, 0);
    for ($i = 1; $i < $m; $i++) {
        $j = $fail[$i - 1];
        while ($j > 0 && $s[$i] != $s[$j]) {
            $j = $fail[$j - 1];
        }
        if ($s[$i] == $s[$j]) {
            $j++;
        }
        $fail[$i] = $j;
    }

    // DP[i][j] = number of ways to build first i characters of t, with current KMP state j
    $dp = array_fill(0, $n + 1, array_fill(0, $m + 1, 0));
    $dp[0][0] = 1;

    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $m; $j++) {
            if ($dp[$i][$j] == 0) continue;

            for ($c = 0; $c <= 1; $c++) {
                $ch = $c == 0 ? '0' : '1';
                $nj = $j;
                while ($nj > 0 && $ch != $s[$nj]) {
                    $nj = $fail[$nj - 1];
                }
                if ($ch == $s[$nj]) {
                    $nj++;
                }

                if ($nj < $m) {
                    $dp[$i + 1][$nj] += $dp[$i][$j];
                }
            }
        }
    }

    // Total valid strings = total strings - strings that never reach state m
    $total = 1 << $n;
    $invalid = 0;
    for ($j = 0; $j < $m; $j++) {
        $invalid += $dp[$n][$j];
    }

    echo $total - $invalid;
}

main();
?>
